// Network-only worker: never cache staff sessions, prices, orders or payments.
self.addEventListener('install', () => self.skipWaiting())
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()))
const orderIdPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
self.addEventListener('push', (event) => {
  let payload = {}
  try { payload = event.data?.json() || {} } catch { /* Always display a generic notification. */ }
  const app = payload.app === 'counter' ? 'counter' : 'admin'
  // Order event tags are generated by the server as UUID:new|paid|ready.
  const match = typeof payload.tag === 'string' && payload.tag.match(/^([0-9a-f-]+):(new|paid|ready)$/i)
  const orderId = match && orderIdPattern.test(match[1]) ? match[1] : null
  event.waitUntil(self.registration.showNotification(payload.title || 'Café update', {
    body: payload.body || 'Open the café app to review.',
    icon: `/staff-${app}-192.png`,
    badge: '/staff-badge.png',
    tag: payload.tag || 'cafe-update',
    data: { app, orderId },
  }))
})
self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const path = event.notification.data?.app === 'counter' ? '/counter' : '/admin'
  const targetUrl = new URL(path, self.location.origin)
  const orderId = event.notification.data?.orderId
  if (typeof orderId === 'string' && orderIdPattern.test(orderId)) targetUrl.searchParams.set('order', orderId)
  const target = targetUrl.href
  event.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(async (clients) => {
    const existing = clients.find((client) => new URL(client.url).pathname === path) || clients.find((client) => ['/admin', '/counter'].includes(new URL(client.url).pathname))
    if (existing) {
      // Focus alone retains the old tab/selection. Navigate to this event first.
      if (targetUrl.search || new URL(existing.url).pathname !== path) {
        try {
          const navigated = existing.navigate && await existing.navigate(target)
          if (navigated) return navigated.focus()
        } catch { /* Fall back to opening the requested order. */ }
        return self.clients.openWindow(target)
      }
      return existing.focus()
    }
    return self.clients.openWindow(target)
  }))
})
